package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import com.ruoyi.medical.identity.ApplicationSessionIdentity;import java.util.*;import java.time.Duration;import org.springframework.beans.factory.ObjectProvider;import org.springframework.util.function.ThrowingSupplier;
/** Server-side publication button: original intent, actual bounded object transfer, then atomic CAS/registration. */
public final class FormalAgentPublicationService {
 private final FormalPublicationReceiptSchema receipts;private final EnterpriseAccess access;private final FormalAgentPublicationSchema schema;private final PermissionSchema json;private final FormalAgentAcceptanceStore acceptances;private final FormalAgentPublicationAuthorization authority;private final FormalAgentPublicationObjectLedger ledger;private final FormalAgentPublicationRegistration registrations;private final AgentPublicationAuthority published;private final ObjectProvider<PublicationEvidenceRevalidation> evidence;private final ObjectProvider<RuntimeObjectTransport> transports;
 public FormalAgentPublicationService(EnterpriseAccess access,FormalAgentPublicationSchema schema,PermissionSchema json,FormalAgentAcceptanceStore acceptances,FormalAgentPublicationAuthorization authority,FormalAgentPublicationObjectLedger ledger,FormalAgentPublicationRegistration registrations,AgentPublicationAuthority published,ObjectProvider<PublicationEvidenceRevalidation> evidence,ObjectProvider<RuntimeObjectTransport> transports)throws java.io.IOException{this.receipts=new FormalPublicationReceiptSchema();this.access=access;this.schema=schema;this.json=json;this.acceptances=acceptances;this.authority=authority;this.ledger=ledger;this.registrations=registrations;this.published=published;this.evidence=evidence;this.transports=transports;}
 public JsonNode publish(ApplicationSessionIdentity.Verified subject,String context,String key,byte[] bytes)throws Exception{
  var request=schema.request("Publish",bytes).deepCopy();SimulationInputArtifactSchema.key(key);var prior=access.execute(subject,a->checked(()->{current(a,context);var row=ledger.inspect(a,key);if(row!=null&&!row.request().equals(schema.canonical(request)))throw new TenantAccessException(ErrorCode.IDEMPOTENCY_CONFLICT);return row!=null&&ledger.completed(a,row)?row:null;}));if(prior!=null)return receipt(subject,context,key);
  var reference=FormalAgentCandidateDependencies.basis(request.required("acceptance"));var original=access.execute(subject,a->checked(()->{current(a,context);return acceptances.metadata(a,reference,"AGENT_PUBLICATION");}));var adapter=evidence.getIfAvailable();var transport=transports.getIfAvailable();if(adapter==null||transport==null)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);
  var prepared=adapter.prepare(subject,context,original.content().deepCopy(),false);var attempt=access.execute(subject,a->checked(()->{current(a,context);var proof=authority.require(a,reference,true,false,prepared);return ledger.prepare(a,key,request,proof);}));
  long deadline=System.nanoTime()+Duration.ofSeconds(60).toNanos();var guard=new S3ObjectReader.Admission(){public void requireCurrent(){if(System.nanoTime()>=deadline)throw new TenantAccessException(ErrorCode.DEPENDENCY_UNAVAILABLE);access.execute(subject,a->checked(()->{current(a,context);authority.require(a,reference,true,false,prepared);ledger.requireAttempt(a,attempt);return null;}));}public Duration remainingTime(){requireCurrent();return Duration.ofNanos(Math.max(1,deadline-System.nanoTime()));}};
  var actual=transport.transferVerified(attempt,guard);
  return access.execute(subject,a->checked(()->{current(a,context);var proof=authority.require(a,reference,true,false,prepared);var registered=registrations.finish(a,attempt,actual,proof);return receipts.validate(publicReceipt(registered));}));
 }
 /** Original key lookup does not create attempts, write objects, finish the operation or cancel it. */
 public JsonNode receipt(ApplicationSessionIdentity.Verified subject,String context,String key)throws Exception{
  SimulationInputArtifactSchema.key(key);var original=access.execute(subject,a->checked(()->{current(a,context);var row=ledger.inspect(a,key);if(row==null)throw new TenantAccessException(ErrorCode.OBJECT_UNAVAILABLE);var reference=new PermissionProtocol.Basis(row.acceptance(),row.acceptanceHash());acceptances.metadata(a,reference,"AGENT_PUBLICATION");return new Recovery(row,ledger.completed(a,row));}));
  if(!original.completed()){return receipts.validate(json.object().put("schema_version","1.0.0").put("state","PROCESSING").put("operation_id",original.row().operation()).put("release_id",original.row().release()).put("request_body_sha256",schema.hash(schema.read(original.row().request()))));}
  var prepared=published.prepare(subject,context,original.row().release(),"AGENT_PUBLICATION",true);return access.execute(subject,a->checked(()->{current(a,context);published.requireHistoricalRead(a,original.row().release(),"AGENT_PUBLICATION",prepared);var row=ledger.inspect(a,key);if(row==null||!row.equals(original.row())||!ledger.completed(a,row))throw new TenantAccessException(ErrorCode.SCOPE_STALE);return receipts.validate(json.object().put("schema_version","1.0.0").put("state","COMPLETED").put("operation_id",row.operation()).put("release_id",row.release()).put("artifact_id",row.artifact()).put("manifest_sha256",row.payloadHash()).put("request_body_sha256",schema.hash(schema.read(row.request()))));}));
 }
 static JsonNode publicReceipt(JsonNode actual){var result=com.fasterxml.jackson.databind.node.JsonNodeFactory.instance.objectNode().put("schema_version","1.0.0").put("state","COMPLETED");for(String key:List.of("operation_id","release_id","artifact_id","manifest_sha256","request_body_sha256"))result.set(key,actual.required(key).deepCopy());return result;}
 private record Recovery(FormalAgentPublicationObjectLedger.Row row,boolean completed){}
 private static void current(EnterpriseAccess.Admission a,String context){if(!a.context().context_revision().equals(context))throw new TenantAccessException(ErrorCode.CONTEXT_CHANGED);}private static <T>T checked(ThrowingSupplier<T> fn){return fn.get();}
}
